"""Independent buyer/provider studies using existing quotes, cash engine and records."""
CSS='''
[data-view=propuestas] #po-option-studies{margin:16px 0;padding:16px;border:1px solid var(--guide-border,#c6d7ed);border-radius:14px;background:var(--guide-surface,#fff);color:var(--guide-ink,#102748)}
[data-view=propuestas] .po-option-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
[data-view=propuestas] .po-option-card{overflow-wrap:anywhere;border:1px solid var(--guide-border,#c6d7ed);border-radius:12px;padding:14px;min-width:0}
[data-view=propuestas] .po-option-card[data-selected=true]{border:2px solid #1553f0}
[data-view=propuestas] .po-option-card strong,[data-view=propuestas] .po-option-card span{display:block;margin:6px 0}
[data-view=propuestas] .po-option-card strong{font-family:var(--eios-display);font-size:22px;font-variant-numeric:tabular-nums}
[data-view=propuestas] .po-option-verdict{padding:8px 10px;border-radius:8px;background:var(--guide-soft,#f4f6fb)}
[data-view=propuestas] .po-option-verdict[data-tone=red]{color:#8b2922;background:#ffebe8}
[data-view=propuestas] .po-option-verdict[data-tone=green]{color:#0b5c4a;background:#e3f4ee}
[data-view=propuestas] .po-option-context{padding:10px;border-left:3px solid #1553f0;background:var(--guide-soft,#f4f6fb);font-weight:600}
[data-view=propuestas] #po-option-studies button{min-height:44px;font:inherit;padding:9px 12px}
[data-view=propuestas] #po-option-studies details{margin-bottom:0}
[data-view=propuestas] #po-option-studies p{font-size:14px;line-height:1.5}
[data-view=propuestas] #po-study-state[data-mode=draft] .po-state-grid{grid-template-columns:minmax(0,1fr)}
@media(max-width:650px){[data-view=propuestas] .po-option-cards{grid-template-columns:minmax(0,1fr)}}
'''
JS=r'''
(function purchaseOptionStudies(){
 const form=$('form'),names={mine:'Mi propuesta',response:'Propuesta del proveedor'},slots=['mine','response'];
 const selected=document.createElement('input');selected.type='hidden';selected.name='negotiation_selected_slot';form.append(selected);
 const panel=document.createElement('section');panel.id='po-option-studies';const marker=document.createComment('independent negotiation studies');$('po-draft-negotiation').closest('.po-negotiation-scroll').after(marker,panel);
 const saveChoice=document.createElement('p');saveChoice.id='po-option-save-choice';saveChoice.className='po-option-context';$('po-guide-save-fields').prepend(saveChoice);
 const planChoice=document.createElement('p');planChoice.id='po-option-plan-choice';planChoice.className='po-option-context';$('proposal-payment-plan').prepend(planChoice);
 let owner=window.purchaseNegotiationSelection(),calendars={},results={},historical=null,sequence=0,timer,controller,identity=null;
 const rawDraft=purchaseNegotiationDraft;
 function saved(){return document.body.dataset.purchaseMode==='saved'}
 function selection(){return window.purchaseNegotiationSelection()}
 function readCalendar(){return {enabled:$('payment-plan-enabled').checked,rows:Array.from($('payment-plan-rows').children).map(row=>Object.fromEntries(['component','amount','due_date'].map(key=>[key,row.querySelector('[data-payment-field='+key+']').value])))}}
 function writeCalendar(calendar){$('payment-plan-enabled').checked=!!calendar?.enabled;$('payment-plan-rows').replaceChildren();for(const data of calendar?.rows||[]){addPaymentRow();const row=$('payment-plan-rows').lastElementChild;for(const key of ['component','amount','due_date'])row.querySelector('[data-payment-field='+key+']').value=data[key]??''}paymentRowsEnabled()}
 function stash(){if(owner)calendars[owner]=readCalendar()}
 function plan(slot){const calendar=slot===owner?readCalendar():calendars[slot];if(!calendar?.enabled)return null;try{return calendar.rows.map(row=>({...row,due_date:inputDateISO(row.due_date)}))}catch(error){throw Error(names[slot]+' · Calendario de pagos: '+error.message)}}
 function followSelection(){const next=selection();if(next!==owner){stash();owner=next;writeCalendar(calendars[next]);schedulePurchaseCash()}selected.value=rawDraft().some(e=>e.slot===next)?next:'';planChoice.textContent='Calendario de '+names[next]+' · Solo se aplica a esta opción. Sin cuotas declaradas, la simulación supone pago único en sus vencimientos.';saveChoice.textContent='Opción del estudio que vas a guardar: '+names[next]+'. Guardar no significa aceptar condiciones.';if(!selected.value){planChoice.textContent='Activa una propuesta para definir y estudiar su calendario de pagos.';saveChoice.textContent='Activa una propuesta y elige su estudio antes de guardar.'}}
 purchaseNegotiationDraft=()=>rawDraft().map(entry=>({...entry,patch:{...entry.patch,payment_installments:plan(entry.slot)}}));
 window.loadPurchaseOptionCalendars=(entries,preferred)=>{calendars={};const target=preferred||entries.find(e=>e.slot==='mine')?.slot||entries[0]?.slot||'mine';for(const entry of entries){const rows=entry.patch.payment_installments;if(Array.isArray(rows))calendars[entry.slot]={enabled:true,rows:rows.map(row=>({...row,due_date:stockDate(row.due_date)}))}}if(!calendars[target]&&!entries.find(e=>e.slot===target)?.patch.hasOwnProperty('payment_installments'))calendars[target]=readCalendar();owner=target;writeCalendar(calendars[target]);if(entries.some(e=>e.slot===target))window.selectPurchaseNegotiationSlot(target);selected.value=target;};
 function choose(slot){if(saved())return;stash();window.selectPurchaseNegotiationSlot(slot);owner=slot;writeCalendar(calendars[slot]);selected.value=slot;form.dispatchEvent(new Event('change',{bubbles:true}));const detail=$('po-guide-analysis');detail.open=true;purchaseGuideNavigate('po-conditions');detail.scrollIntoView({block:'start'})}
 window.purchaseOpenOptionCalendar=slot=>{choose(slot);purchaseGuideNavigate('po-payments',true)};
 function labelDraft(){if(saved())return;for(const id of ['po-cash','po-purchase-summary','po-alternatives-table']){const box=$(id);if(!box)continue;box.querySelector(':scope>.po-option-context')?.remove();const label=document.createElement('p');label.className='po-option-context';label.textContent='ANALIZANDO: '+names[selection()]+' · Borrador';box.prepend(label);box.dataset.studySlot=selection()}}
 const renderCash=renderPurchaseCash;renderPurchaseCash=function(box,r,editable){renderCash(box,r,editable);if(editable)labelDraft()};
 const apply=applyPurchaseSuggestedAlternative;applyPurchaseSuggestedAlternative=a=>{stash();apply(a);calendars.mine=a.patch.payment_installments?{enabled:true,rows:a.patch.payment_installments.map(row=>({...row,due_date:stockDate(row.due_date)}))}:null;window.selectPurchaseNegotiationSlot('mine');owner='mine';writeCalendar(calendars.mine);selected.value='mine';form.dispatchEvent(new Event('change',{bubbles:true}));$('po-guide-analysis').open=true;};
 function render(){
  panel.replaceChildren();const title=document.createElement('h3');title.textContent='COMPARAR LAS DOS PROPUESTAS';const note=document.createElement('p');note.textContent=historical?'Estudios conservados al guardar. Consultar otra opción no cambia las condiciones del acuerdo ni recalcula el pasado.':'Cada propuesta se estudia con sus precios, impuestos, portes y calendario. Elegir una para analizar no significa aceptarla.';panel.append(title,note);const cards=document.createElement('div');cards.className='po-option-cards';panel.append(cards);
  const entries=historical?.negotiation_at_save?.alternatives||rawDraft();
  for(const slot of slots){const entry=entries.find(e=>e.slot===slot),r=historical?entry?.cash_orientation:results[slot],card=document.createElement('article');card.className='po-option-card';card.dataset.slot=slot;card.dataset.selected=String((historical?historical.negotiation_at_save?.selected_slot:selection())===slot);const heading=document.createElement('h4');heading.textContent=names[slot];card.append(heading);const caption=document.createElement('small');caption.textContent='TOTAL CON IVA Y PORTES';const value=document.createElement('strong'),total=r?.current_terms?.total??(r?.balance_comparison?.amount_basis==='FULL_OPERATION'?r.balance_comparison.purchase_amount:null);value.textContent=total!==null?money(total)+' EUR':'Escenario pendiente de completar';card.append(caption,value);const status=document.createElement('p');status.className='po-option-verdict';status.dataset.tone=r?.status==='SHORTFALL'?'red':r?.status==='WITHIN_DECLARED_SCENARIO'?'green':'neutral';status.textContent=!entry?'Opción sin activar':!r?(historical?'Análisis independiente no conservado en este estudio.':'Calculando esta opción…'):r.status==='SHORTFALL'?'Falta dinero para la reserva':r.status==='WITHIN_DECLARED_SCENARIO'?'Mantiene la reserva en el escenario':'Faltan datos para analizar';card.append(status);
   if(r?.scenario){for(const [label,number] of [['Dinero mínimo previsto',r.scenario.minimum_balance],['Falta para la reserva',r.scenario.deficit]]){const line=document.createElement('span');line.textContent=label+': '+money(number)+' EUR';card.append(line)}}
   if(r?.status==='PENDING'){const reason=document.createElement('p');reason.textContent=r.message;card.append(reason)}
   const button=document.createElement('button');button.type='button';button.textContent=slot==='mine'?'Analizar Mi propuesta':'Analizar Propuesta del proveedor';button.disabled=!entry||!!historical&&!r;button.onclick=()=>{if(!historical){const detail=document.createElement('section');detail.className='po-option-detail';const heading=document.createElement('p');heading.className='po-option-context';heading.textContent=names[slot]+' · Análisis del borrador · No cambia las condiciones elegidas para pagar';detail.append(heading);if(r){const body=document.createElement('div');renderPurchaseCash(body,r,false);renderSavedPurchaseAlternativesTable(body,r);detail.append(body)}panel.querySelector('.po-option-detail')?.remove();panel.append(detail);detail.scrollIntoView({block:'start'});return}const detail=document.createElement('section');detail.className='po-option-detail';const heading=document.createElement('p');heading.className='po-option-context';heading.textContent=names[slot]+' · Estudio guardado · Consulta sin modificar la opción del acuerdo';detail.append(heading);const body=document.createElement('div');renderPurchaseCash(body,r,false);renderSavedPurchaseAlternativesTable(body,r);detail.append(body);panel.querySelector('.po-option-detail')?.remove();panel.append(detail);detail.scrollIntoView({block:'start'})};card.append(button);if(!historical&&entry){const proceed=document.createElement('button');proceed.type='button';proceed.textContent='Continuar con '+names[slot];proceed.onclick=()=>{choose(slot);window.purchasePaymentChoice=slot;form.dispatchEvent(new Event('purchasechoice',{bubbles:true}));purchaseGuideNavigate('po-payments',true)};card.append(proceed)}if(historical?.negotiation_at_save?.selected_slot===slot){const label=document.createElement('small');label.textContent='Opción principal de este estudio guardado y de su eventual declaración de acuerdo.';card.append(label)}if(!historical&&selection()===slot&&entry){const label=document.createElement('small');label.textContent='Condiciones de referencia del formulario. Usa «Continuar con…» para elegirlas expresamente.';card.append(label)}cards.append(card);
  }
 }
 function schedule(){
  if(saved()){++sequence;clearTimeout(timer);controller?.abort();return}
  historical=null;const key=[$('dataset').value,$('supplier').value,$('article').value].join('|');if(identity!==null&&key!==identity){calendars={};owner=selection()}identity=key;followSelection();results={};render();const request=++sequence;clearTimeout(timer);controller?.abort();timer=setTimeout(async()=>{
   if(saved()||request!==sequence||!state)return;controller=new AbortController();const abort=controller,deadline=setTimeout(()=>abort.abort(),30000),dataset=$('dataset').value;
   const base=Object.fromEntries(new FormData(form));base.dataset_id=dataset;base.documentary_context_fingerprint=state.documentary_context.fingerprint;
   await Promise.all(rawDraft().map(async entry=>{try{const data={...base,...entry.patch,payment_installments:plan(entry.slot)};data.stock_planning=purchaseStockPlanningDraft();const result=await api('/api/purchases/cash-preview',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify(data),signal:abort.signal});if(request===sequence&&!saved()&&dataset===$('dataset').value)results[entry.slot]=result}catch(error){if(request===sequence&&!saved()&&dataset===$('dataset').value)results[entry.slot]={status:'PENDING',message:error.name==='AbortError'?'El análisis ha tardado demasiado. Modifica un dato para volver a calcular.':error.message}}}));clearTimeout(deadline);if(request===sequence&&!saved()){const usable=Object.values(results).filter(r=>r.status!=='PENDING'),keys=['documentary_context','financial_source_fingerprint','parameter_activation','opening_balance','treasury_minimum','cutoff','horizon_end'];if(usable.length>1&&keys.some(key=>JSON.stringify(usable[0][key])!==JSON.stringify(usable[1][key])))for(const slot of Object.keys(results))results[slot]={status:'PENDING',message:'Han cambiado las fuentes o criterios financieros. Recarga y vuelve a comparar.'};render();}
  },450)
 }
 const oldFinance=renderFinancialContext;renderFinancialContext=function(report){oldFinance(report);++sequence;clearTimeout(timer);controller?.abort();historical=report.proposal;let done=$('po-save-complete');if(!done){done=document.createElement('section');done.id='po-save-complete';done.className='po-option-context';$('po-save').prepend(done)}done.replaceChildren();const title=document.createElement('h3');title.textContent='ESTUDIO FINALIZADO Y GUARDADO';const description=document.createElement('p');description.textContent='Referencia: '+historical.reference+' · '+(names[historical.negotiation_at_save?.selected_slot]||'Condiciones guardadas')+' · Total: '+money(historical.operation_total)+' EUR · Consulta en solo lectura. El acuerdo con el proveedor se registra por separado.';done.append(title,description);let agreementState=$('po-agreement-study-state');if(!agreementState){agreementState=document.createElement('p');agreementState.id='po-agreement-study-state';agreementState.className='po-option-context';$('po-guide-agreement').querySelector('.po-heading').after(agreementState)}agreementState.textContent='Estudio '+historical.reference+' finalizado y guardado · '+money(historical.operation_total)+' EUR. Este paso registra por separado el acuerdo con el proveedor.';$('po-save').querySelector('.po-guide-result').before(panel);render();const label=names[historical.negotiation_at_save?.selected_slot];if(label){const note=$('po-agreement')?.querySelector('p');if(note)note.append(' Opción del acuerdo: '+label+'.')}};
 new MutationObserver(()=>{if(!saved()){$('po-save-complete')?.remove();$('po-agreement-study-state')?.remove();historical=null;marker.after(panel);schedule()}else{++sequence;clearTimeout(timer);controller?.abort()}}).observe(document.body,{attributes:true,attributeFilter:['data-purchase-mode']});
 for(const type of ['input','change'])form.addEventListener(type,schedule);
 form.addEventListener('click',event=>{if(event.target.closest('#payment-plan-add,#payment-plan-rows button,#payment-split-generate'))schedule()});
 form.addEventListener('reset',()=>{calendars={};owner='mine';historical=null;queueMicrotask(schedule)});$('dataset').addEventListener('change',()=>{calendars={};owner='mine';identity=null;schedule()});
 for(const id of ['summary','proposal-cost-summary'])new MutationObserver(schedule).observe($(id),{childList:true,subtree:true,characterData:true});schedule();
})();
'''
